import React, { useState } from 'react';
import { useIntermittence } from '../context/IntermittenceContext';
import { Plus, Trash, HelpCircle, Save, History, X } from 'lucide-react';
import ImportExportBar from '../components/ImportExportBar';

const ContratsPage: React.FC = () => {
  const { data, updateContrat, addContrat, removeContrat, sauvegarderPeriode, restaurerPeriode, supprimerPeriode, creerNouvellePeriode, getEmployeurById } = useIntermittence();
  const [afficherPeriodes, setAfficherPeriodes] = useState(false);

  const employeurs = data.employeurs || [];
  
  // Filtrer les contrats pour ne garder que ceux dans la fenêtre de 12 mois POUR LES CALCULS
  // APRÈS la date de fin de contrat (jusqu'à la date anniversaire)
  const getContratsDansFenetre12Mois = () => {
    if (!data.dateFinContrat) {
      return data.contrats;
    }
    
    const dateFinContrat = new Date(data.dateFinContrat);
    // Date anniversaire = 12 mois APRÈS la date de fin de contrat
    const dateAnniversaire = new Date(dateFinContrat);
    dateAnniversaire.setFullYear(dateAnniversaire.getFullYear() + 1);
    
    return data.contrats.filter(contrat => {
      const dateContrat = new Date(contrat.date);
      // Contrats APRÈS la date de fin et AVANT la date anniversaire
      return dateContrat > dateFinContrat && dateContrat <= dateAnniversaire;
    });
  };
  
  // Fonction pour vérifier si un contrat est dans la période
  const estDansPeriode = (contrat: any) => {
    if (!data.dateFinContrat) return true;
    
    const dateFinContrat = new Date(data.dateFinContrat);
    const dateAnniversaire = new Date(dateFinContrat);
    dateAnniversaire.setFullYear(dateAnniversaire.getFullYear() + 1);
    const dateContrat = new Date(contrat.date);
    
    return dateContrat > dateFinContrat && dateContrat <= dateAnniversaire;
  };
  
  const contratsFiltres = getContratsDansFenetre12Mois();
  
  // Calcul des heures et totaux sur les contrats filtrés
  const totalHeures = contratsFiltres.reduce(
    (acc, c) => acc + (c.type === 'Cachet' ? c.nombre * 12 : c.nombre), 
    0
  );
  
  const totalBrut = contratsFiltres.reduce((acc, c) => acc + c.brut, 0);
  
  const getHeuresConverties = (contrat: { type: string, nombre: number }) => {
    return contrat.type === 'Cachet' ? contrat.nombre * 12 : contrat.nombre;
  };
  
  const getCotisations = (brut: number) => brut * 0.23;
  
  const getNet = (brut: number) => brut - getCotisations(brut);

  return (
    <div className="p-6">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-800 mb-2">Liste des contrats</h1>
        <p className="text-gray-600">
          Saisissez ici tous vos contrats. Les cachets sont automatiquement convertis (12h par cachet).
        </p>
        {data.dateFinContrat && (
          <p className="text-sm text-blue-600 mt-2 bg-blue-50 p-2 rounded">
            ℹ️ Suivi pour le renouvellement : contrats du {new Date(data.dateFinContrat).toLocaleDateString('fr-FR')} au {new Date(new Date(data.dateFinContrat).setFullYear(new Date(data.dateFinContrat).getFullYear() + 1)).toLocaleDateString('fr-FR')} (date anniversaire).
            {data.contrats.length > contratsFiltres.length && (
              <span className="ml-1">({data.contrats.length - contratsFiltres.length} contrat(s) hors période)</span>
            )}
          </p>
        )}
        {!data.dateFinContrat && (
          <p className="text-sm text-amber-600 mt-2 bg-amber-50 p-2 rounded">
            ⚠️ Aucune date de fin de contrat définie. Tous les contrats sont pris en compte. Allez dans "Mon AJ" pour définir votre date d'ouverture de droits.
          </p>
        )}
      </div>
      
      <ImportExportBar />
      
      <div className="bg-white rounded-lg shadow mb-6 overflow-hidden">
        <div className="grid grid-cols-12 bg-gray-800 text-white font-semibold p-3">
          <div className="col-span-2">Date</div>
          <div className="col-span-3">Employeur</div>
          <div className="col-span-1">Type</div>
          <div className="col-span-1">Nombre</div>
          <div className="col-span-1">Brut (€)</div>
          <div className="col-span-1">Heures</div>
          <div className="col-span-1">Cotisations</div>
          <div className="col-span-1">Net</div>
          <div className="col-span-1">Actions</div>
        </div>
        
        {data.contrats.map((contrat, index) => {
          const heuresConverties = getHeuresConverties(contrat);
          const cotisations = getCotisations(contrat.brut);
          const net = getNet(contrat.brut);
          const dansPeriode = estDansPeriode(contrat);
          
          return (
            <div 
              key={index} 
              className={`grid grid-cols-12 items-center p-3 border-b ${
                dansPeriode 
                  ? (index % 2 === 0 ? 'bg-green-50' : 'bg-green-100')
                  : 'bg-gray-100 opacity-60'
              }`}
              title={!dansPeriode ? "Contrat hors période de suivi (non pris en compte dans les calculs)" : ""}
            >
              <div className="col-span-2">
                <input
                  type="date"
                  value={contrat.date}
                  onChange={(e) => updateContrat(index, 'date', e.target.value)}
                  className="w-full p-1 border rounded"
                />
              </div>
              <div className="col-span-3">
                {employeurs.length > 0 ? (
                  <div className="flex gap-1">
                    <select
                      value={contrat.employeurId || ''}
                      onChange={(e) => {
                        if (e.target.value) {
                          const emp = getEmployeurById(e.target.value);
                          if (emp) {
                            updateContrat(index, 'employeur', emp.nom);
                            updateContrat(index, 'employeurId', emp.id);
                          }
                        }
                      }}
                      className="w-1/2 p-1 border rounded text-sm"
                    >
                      <option value="">Sélectionner...</option>
                      {employeurs.map(emp => (
                        <option key={emp.id} value={emp.id}>{emp.nom}</option>
                      ))}
                    </select>
                    <input
                      type="text"
                      value={contrat.employeur}
                      onChange={(e) => {
                        updateContrat(index, 'employeur', e.target.value);
                        updateContrat(index, 'employeurId', '');
                      }}
                      className="w-1/2 p-1 border rounded text-sm"
                      placeholder="Ou saisir..."
                    />
                  </div>
                ) : (
                  <input
                    type="text"
                    value={contrat.employeur}
                    onChange={(e) => updateContrat(index, 'employeur', e.target.value)}
                    className="w-full p-1 border rounded"
                    placeholder="Nom de l'employeur"
                  />
                )}
              </div>
              <div className="col-span-1">
                <select
                  value={contrat.type}
                  onChange={(e) => updateContrat(index, 'type', e.target.value as 'Cachet' | 'Heures')}
                  className="w-full p-1 border rounded"
                >
                  <option value="Cachet">Cachet</option>
                  <option value="Heures">Heures</option>
                </select>
              </div>
              <div className="col-span-1">
                <input
                  type="number"
                  value={contrat.nombre}
                  onChange={(e) => updateContrat(index, 'nombre', parseInt(e.target.value) || 0)}
                  className="w-full p-1 border rounded"
                  min="0"
                />
              </div>
              <div className="col-span-1">
                <input
                  type="number"
                  value={contrat.brut}
                  onChange={(e) => updateContrat(index, 'brut', parseFloat(e.target.value) || 0)}
                  className="w-full p-1 border rounded"
                  min="0"
                />
              </div>
              <div className="col-span-1 bg-orange-100 p-1 text-center rounded">
                {heuresConverties}
              </div>
              <div className="col-span-1 bg-orange-100 p-1 text-center rounded">
                {cotisations.toFixed(2)}
              </div>
              <div className="col-span-1 bg-orange-100 p-1 text-center rounded">
                {net.toFixed(2)}
              </div>
              <div className="col-span-1 flex justify-center">
                <button 
                  onClick={() => removeContrat(index)}
                  className="p-1 text-red-600 hover:bg-red-100 rounded"
                >
                  <Trash className="w-4 h-4" />
                </button>
              </div>
            </div>
          );
        })}
        
        {/* Bouton ajouter */}
        <div className="p-3 border-t">
          <button 
            onClick={addContrat}
            className="flex items-center text-green-600 hover:bg-green-50 p-2 rounded"
          >
            <Plus className="w-4 h-4 mr-1" />
            Ajouter un contrat
          </button>
        </div>
      </div>
      
      {/* Section de gestion des périodes */}
      <div className="bg-purple-50 rounded-lg p-4 border border-purple-200 mb-6">
        <div className="flex items-center justify-between mb-3">
          <h2 className="text-lg font-semibold flex items-center">
            <History className="w-5 h-5 mr-2 text-purple-600" />
            Gestion des périodes (renouvellements)
          </h2>
          <div className="flex gap-2">
            <button
              onClick={creerNouvellePeriode}
              className="flex items-center px-3 py-2 bg-green-600 text-white rounded hover:bg-green-700 transition"
              title="Créer une nouvelle période après renouvellement"
            >
              <Plus className="w-4 h-4 mr-1" />
              Nouvelle période
            </button>
            <button
              onClick={sauvegarderPeriode}
              className="flex items-center px-3 py-2 bg-purple-600 text-white rounded hover:bg-purple-700 transition"
              title="Sauvegarder la période actuelle"
            >
              <Save className="w-4 h-4 mr-1" />
              Sauvegarder période
            </button>
            <button
              onClick={() => setAfficherPeriodes(!afficherPeriodes)}
              className="flex items-center px-3 py-2 bg-purple-100 text-purple-700 rounded hover:bg-purple-200 transition"
            >
              <History className="w-4 h-4 mr-1" />
              {afficherPeriodes ? 'Masquer' : 'Voir'} historique
            </button>
          </div>
        </div>
        <p className="text-sm text-purple-700 mb-3">
          <strong>Renouvellement :</strong> Cliquez sur "Nouvelle période" pour sauvegarder votre AJ actuelle et créer une nouvelle période avec une nouvelle AJ. Vos anciennes données restent consultables dans l'historique.
        </p>
        
        {afficherPeriodes && data.periodesSauvegardees && data.periodesSauvegardees.length > 0 && (
          <div className="mt-4 space-y-2">
            <h3 className="font-semibold text-purple-800 mb-2">Périodes sauvegardées :</h3>
            {data.periodesSauvegardees.map((periode) => (
              <div key={periode.id} className="bg-white rounded-lg p-3 border border-purple-200">
                <div className="flex items-start justify-between">
                  <div className="flex-1">
                    <div className="font-semibold text-purple-800">
                      Période du {new Date(periode.dateSauvegarde).toLocaleDateString('fr-FR')}
                    </div>
                    <div className="text-sm text-gray-600 mt-1">
                      <div><strong>AJ :</strong> {periode.ajNette} € net • {periode.ajBrute} € brut</div>
                      <div><strong>Période :</strong> {new Date(periode.dateFinContrat).toLocaleDateString('fr-FR')} → {new Date(new Date(periode.dateFinContrat).setFullYear(new Date(periode.dateFinContrat).getFullYear() + 1)).toLocaleDateString('fr-FR')}</div>
                      <div><strong>Contrats :</strong> {periode.contrats.length} contrat(s) • {periode.totalHeures.toFixed(0)} heures • {periode.totalBrut.toFixed(2)} €</div>
                    </div>
                  </div>
                  <div className="flex gap-2 ml-4">
                    <button
                      onClick={() => restaurerPeriode(periode.id)}
                      className="px-3 py-1 bg-blue-100 text-blue-700 rounded hover:bg-blue-200 text-sm"
                      title="Restaurer cette période"
                    >
                      Restaurer
                    </button>
                    <button
                      onClick={() => supprimerPeriode(periode.id)}
                      className="px-3 py-1 bg-red-100 text-red-700 rounded hover:bg-red-200 text-sm"
                      title="Supprimer cette période"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
        
        {afficherPeriodes && (!data.periodesSauvegardees || data.periodesSauvegardees.length === 0) && (
          <div className="mt-4 text-sm text-gray-600 italic">
            Aucune période sauvegardée pour le moment.
          </div>
        )}
      </div>

      {/* Résumé des heures et des montants */}
      <div className="bg-blue-50 rounded-lg p-4 border border-blue-200">
        <h2 className="text-lg font-semibold mb-2 flex items-center">
          <HelpCircle className="w-4 h-4 mr-1 text-blue-600" />
          Récapitulatif
        </h2>
        <div className="grid grid-cols-3 gap-4">
          <div className="bg-white p-3 rounded border shadow-sm">
            <div className="text-sm text-gray-600">Total heures</div>
            <div className="text-xl font-bold">{totalHeures.toFixed(2)} heures</div>
            <div className="text-xs text-gray-500">
              {totalHeures >= 507 
                ? "✅ Seuil de 507h atteint" 
                : `❌ Il manque ${(507 - totalHeures).toFixed(2)}h pour atteindre le seuil de 507h`}
            </div>
          </div>
          <div className="bg-white p-3 rounded border shadow-sm">
            <div className="text-sm text-gray-600">Total brut</div>
            <div className="text-xl font-bold">{totalBrut.toFixed(2)} €</div>
          </div>
          <div className="bg-white p-3 rounded border shadow-sm">
            <div className="text-sm text-gray-600">Total net estimé</div>
            <div className="text-xl font-bold">{(totalBrut * 0.77).toFixed(2)} €</div>
            <div className="text-xs text-gray-500">Après déduction des cotisations sociales (~23%)</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ContratsPage; 