import React, { useState } from 'react';
import { useIntermittence } from '../context/IntermittenceContext';
import { Plus, Trash, Edit2, Save, X, Building2 } from 'lucide-react';
import ImportExportBar from '../components/ImportExportBar';

const EmployeursPage: React.FC = () => {
  const { data, addEmployeur, updateEmployeur, removeEmployeur } = useIntermittence();
  const [modeEdition, setModeEdition] = useState<string | null>(null);
  const [nouvelEmployeur, setNouvelEmployeur] = useState({
    nom: '',
    siret: '',
    adresse: '',
    ville: '',
    codePostal: ''
  });
  const [afficherFormulaire, setAfficherFormulaire] = useState(false);

  const handleAjouterEmployeur = () => {
    if (!nouvelEmployeur.nom.trim()) {
      alert('Le nom de l\'employeur est obligatoire');
      return;
    }

    addEmployeur(nouvelEmployeur);
    setNouvelEmployeur({
      nom: '',
      siret: '',
      adresse: '',
      ville: '',
      codePostal: ''
    });
    setAfficherFormulaire(false);
  };

  const handleModifierEmployeur = (id: string, field: string, value: string) => {
    updateEmployeur(id, { [field]: value });
  };

  const employeurs = data.employeurs || [];

  return (
    <div className="p-6">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-800 mb-2">Liste des employeurs</h1>
        <p className="text-gray-600">
          Gérez votre liste d'employeurs pour une saisie rapide des contrats.
        </p>
      </div>

      <ImportExportBar />

      {/* Bouton Ajouter */}
      <div className="mb-6">
        <button
          onClick={() => setAfficherFormulaire(!afficherFormulaire)}
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
        >
          {afficherFormulaire ? <X className="w-4 h-4" /> : <Plus className="w-4 h-4" />}
          {afficherFormulaire ? 'Annuler' : 'Ajouter un employeur'}
        </button>
      </div>

      {/* Formulaire d'ajout */}
      {afficherFormulaire && (
        <div className="bg-white rounded-lg shadow p-6 mb-6">
          <h3 className="text-lg font-semibold mb-4">Nouvel employeur</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Nom de l'employeur *
              </label>
              <input
                type="text"
                value={nouvelEmployeur.nom}
                onChange={(e) => setNouvelEmployeur({ ...nouvelEmployeur, nom: e.target.value })}
                className="w-full p-2 border rounded-md"
                placeholder="Théâtre ABC"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                SIRET
              </label>
              <input
                type="text"
                value={nouvelEmployeur.siret}
                onChange={(e) => setNouvelEmployeur({ ...nouvelEmployeur, siret: e.target.value })}
                className="w-full p-2 border rounded-md"
                placeholder="123 456 789 00012"
              />
            </div>
            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Adresse
              </label>
              <input
                type="text"
                value={nouvelEmployeur.adresse}
                onChange={(e) => setNouvelEmployeur({ ...nouvelEmployeur, adresse: e.target.value })}
                className="w-full p-2 border rounded-md"
                placeholder="12 rue du Spectacle"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Code postal
              </label>
              <input
                type="text"
                value={nouvelEmployeur.codePostal}
                onChange={(e) => setNouvelEmployeur({ ...nouvelEmployeur, codePostal: e.target.value })}
                className="w-full p-2 border rounded-md"
                placeholder="75001"
              />
            </div>
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Ville
              </label>
              <input
                type="text"
                value={nouvelEmployeur.ville}
                onChange={(e) => setNouvelEmployeur({ ...nouvelEmployeur, ville: e.target.value })}
                className="w-full p-2 border rounded-md"
                placeholder="Paris"
              />
            </div>
          </div>
          <div className="mt-4 flex gap-2">
            <button
              onClick={handleAjouterEmployeur}
              className="flex items-center gap-2 px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700"
            >
              <Save className="w-4 h-4" />
              Enregistrer
            </button>
            <button
              onClick={() => {
                setAfficherFormulaire(false);
                setNouvelEmployeur({
                  nom: '',
                  siret: '',
                  adresse: '',
                  ville: '',
                  codePostal: ''
                });
              }}
              className="px-4 py-2 bg-gray-300 text-gray-700 rounded-md hover:bg-gray-400"
            >
              Annuler
            </button>
          </div>
        </div>
      )}

      {/* Liste des employeurs */}
      <div className="bg-white rounded-lg shadow overflow-hidden">
        {employeurs.length === 0 ? (
          <div className="p-8 text-center text-gray-500">
            <Building2 className="w-12 h-12 mx-auto mb-3 text-gray-400" />
            <p>Aucun employeur enregistré.</p>
            <p className="text-sm mt-1">Ajoutez vos employeurs pour une saisie rapide des contrats.</p>
          </div>
        ) : (
          <div className="divide-y">
            {employeurs.map((employeur) => (
              <div key={employeur.id} className="p-4 hover:bg-gray-50">
                {modeEdition === employeur.id ? (
                  // Mode édition
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                    <div>
                      <label className="block text-xs font-medium text-gray-600 mb-1">Nom *</label>
                      <input
                        type="text"
                        value={employeur.nom}
                        onChange={(e) => handleModifierEmployeur(employeur.id, 'nom', e.target.value)}
                        className="w-full p-2 border rounded-md text-sm"
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-gray-600 mb-1">SIRET</label>
                      <input
                        type="text"
                        value={employeur.siret || ''}
                        onChange={(e) => handleModifierEmployeur(employeur.id, 'siret', e.target.value)}
                        className="w-full p-2 border rounded-md text-sm"
                      />
                    </div>
                    <div className="md:col-span-2">
                      <label className="block text-xs font-medium text-gray-600 mb-1">Adresse</label>
                      <input
                        type="text"
                        value={employeur.adresse || ''}
                        onChange={(e) => handleModifierEmployeur(employeur.id, 'adresse', e.target.value)}
                        className="w-full p-2 border rounded-md text-sm"
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-gray-600 mb-1">Code postal</label>
                      <input
                        type="text"
                        value={employeur.codePostal || ''}
                        onChange={(e) => handleModifierEmployeur(employeur.id, 'codePostal', e.target.value)}
                        className="w-full p-2 border rounded-md text-sm"
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-medium text-gray-600 mb-1">Ville</label>
                      <input
                        type="text"
                        value={employeur.ville || ''}
                        onChange={(e) => handleModifierEmployeur(employeur.id, 'ville', e.target.value)}
                        className="w-full p-2 border rounded-md text-sm"
                      />
                    </div>
                    <div className="md:col-span-2 flex gap-2 mt-2">
                      <button
                        onClick={() => setModeEdition(null)}
                        className="flex items-center gap-1 px-3 py-1 bg-green-600 text-white rounded text-sm hover:bg-green-700"
                      >
                        <Save className="w-3 h-3" />
                        Enregistrer
                      </button>
                      <button
                        onClick={() => setModeEdition(null)}
                        className="px-3 py-1 bg-gray-300 text-gray-700 rounded text-sm hover:bg-gray-400"
                      >
                        Annuler
                      </button>
                    </div>
                  </div>
                ) : (
                  // Mode affichage
                  <div className="flex items-start justify-between">
                    <div className="flex-grow">
                      <h3 className="font-semibold text-lg text-gray-800">{employeur.nom}</h3>
                      <div className="mt-2 space-y-1 text-sm text-gray-600">
                        {employeur.siret && (
                          <p><span className="font-medium">SIRET:</span> {employeur.siret}</p>
                        )}
                        {employeur.adresse && (
                          <p><span className="font-medium">Adresse:</span> {employeur.adresse}</p>
                        )}
                        {(employeur.codePostal || employeur.ville) && (
                          <p>
                            {employeur.codePostal} {employeur.ville}
                          </p>
                        )}
                      </div>
                    </div>
                    <div className="flex gap-2 ml-4">
                      <button
                        onClick={() => setModeEdition(employeur.id)}
                        className="p-2 text-blue-600 hover:bg-blue-50 rounded"
                        title="Modifier"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => removeEmployeur(employeur.id)}
                        className="p-2 text-red-600 hover:bg-red-50 rounded"
                        title="Supprimer"
                      >
                        <Trash className="w-4 h-4" />
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Statistiques */}
      {employeurs.length > 0 && (
        <div className="mt-6 bg-blue-50 rounded-lg p-4">
          <p className="text-sm text-blue-800">
            <strong>{employeurs.length}</strong> employeur{employeurs.length > 1 ? 's' : ''} enregistré{employeurs.length > 1 ? 's' : ''}
          </p>
        </div>
      )}
    </div>
  );
};

export default EmployeursPage;
