import React, { createContext, useState, useContext, ReactNode } from 'react';

interface Employeur {
  id: string;
  nom: string;
  siret?: string;
  adresse?: string;
  ville?: string;
  codePostal?: string;
}

interface Contrat {
  date: string;
  employeur: string;
  employeurId?: string; // ID de l'employeur dans la liste
  type: 'Cachet' | 'Heures';
  nombre: number;
  brut: number;
  statut?: 'complet' | 'incomplet' | 'impaye'; // Statut du contrat
  notes?: string;
}

interface IntermittenceData {
  // Données générales
  annexe: string;
  montantNet: string;
  dateIndem: string;
  dateFinContrat: string;
  delaiAttente: boolean;
  franchiseConges: string;
  joursConges: string;
  franchiseSalaires: string;
  joursSalaires: string;
  ajNette: string;
  ajBrute: string;
  tauxPrelevement: string;
  // Liste des contrats
  contrats: Contrat[];
  // Liste des employeurs
  employeurs?: Employeur[];
  // Périodes sauvegardées (pour les renouvellements)
  periodesSauvegardees?: PeriodeSauvegardee[];
  // Contrats simulés (pour l'examen anticipé)
  contratsSimules?: Contrat[];
}

interface PeriodeSauvegardee {
  id: string;
  dateSauvegarde: string;
  dateFinContrat: string;
  dateIndem: string;
  // Toutes les données AJ de la période
  montantNet: string;
  ajNette: string;
  ajBrute: string;
  tauxPrelevement: string;
  delaiAttente: boolean;
  franchiseConges: string;
  joursConges: string;
  franchiseSalaires: string;
  joursSalaires: string;
  annexe: string;
  // Contrats et calculs de la période
  contrats: Contrat[];
  totalHeures: number;
  totalBrut: number;
}

interface IntermittenceContextProps {
  data: IntermittenceData;
  setData: React.Dispatch<React.SetStateAction<IntermittenceData>>;

  // Fonctions utilitaires
  updateField: (field: keyof IntermittenceData, value: any) => void;
  updateContrat: (index: number, field: keyof Contrat, value: any) => void;
  addContrat: () => void;
  removeContrat: (index: number) => void;

  // Gestion des employeurs
  addEmployeur: (employeur: Omit<Employeur, 'id'>) => void;
  updateEmployeur: (id: string, employeur: Partial<Employeur>) => void;
  removeEmployeur: (id: string) => void;
  getEmployeurById: (id: string) => Employeur | undefined;

  // Gestion des périodes
  sauvegarderPeriode: () => void;
  restaurerPeriode: (periodeId: string) => void;
  supprimerPeriode: (periodeId: string) => void;
  creerNouvellePeriode: () => void;

  // Simulation (examen anticipé)
  addContratSimule: (contrat: Omit<Contrat, 'statut'>) => void;
  updateContratSimule: (index: number, field: keyof Contrat, value: any) => void;
  removeContratSimule: (index: number) => void;
  clearContratsSimules: () => void;

  // Détection d'anomalies
  detecterAnomalies: () => {
    incomplets: Contrat[];
    impayes: Contrat[];
    doublons: Contrat[][];
  };

  // Import/Export
  exportData: () => void;
  importData: (jsonData: string) => void;
}

const defaultData: IntermittenceData = {
  annexe: 'Ouvrier/Technicien (Annexe 8)',
  montantNet: '',
  dateIndem: '',
  dateFinContrat: '',
  delaiAttente: false,
  franchiseConges: '',
  joursConges: '',
  franchiseSalaires: '',
  joursSalaires: '',
  ajNette: '',
  ajBrute: '',
  tauxPrelevement: '0',
  contrats: [
    { date: '2024-01-01', employeur: 'Théâtre ABC', type: 'Cachet', nombre: 2, brut: 600 },
    { date: '2024-01-15', employeur: 'Production XYZ', type: 'Heures', nombre: 35, brut: 875 },
    { date: '2024-02-01', employeur: 'Festival 123', type: 'Cachet', nombre: 3, brut: 900 }
  ],
};

export const IntermittenceContext = createContext<IntermittenceContextProps>({} as IntermittenceContextProps);

export const useIntermittence = () => useContext(IntermittenceContext);

// Fonction utilitaire pour filtrer les contrats dans la fenêtre de 12 mois
// IMPORTANT : Pour le suivi du prochain renouvellement, on prend les contrats
// APRÈS la date de fin de contrat jusqu'à la date anniversaire (12 mois après)
export const getContratsDansFenetre12Mois = (contrats: Contrat[], dateFinContrat?: string): Contrat[] => {
  if (!dateFinContrat) {
    // Si pas de date de fin de contrat, on prend tous les contrats
    return contrats;
  }

  const dateDebutPeriode = new Date(dateFinContrat);
  // Date anniversaire = 12 mois APRÈS la date de fin de contrat
  const dateAnniversaire = new Date(dateDebutPeriode);
  dateAnniversaire.setFullYear(dateAnniversaire.getFullYear() + 1);

  return contrats.filter(contrat => {
    const dateContrat = new Date(contrat.date);
    // Contrats APRÈS la date de fin et AVANT/ÉGAL la date anniversaire
    return dateContrat > dateDebutPeriode && dateContrat <= dateAnniversaire;
  });
};

export const IntermittenceProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [data, setData] = useState<IntermittenceData>(defaultData);

  const updateField = (field: keyof IntermittenceData, value: any) => {
    setData(prev => ({ ...prev, [field]: value }));
  };

  const updateContrat = (index: number, field: keyof Contrat, value: any) => {
    setData(prev => {
      const newContrats = [...prev.contrats];
      newContrats[index] = { ...newContrats[index], [field]: value };
      return { ...prev, contrats: newContrats };
    });
  };

  const addContrat = () => {
    setData(prev => ({
      ...prev,
      contrats: [
        ...prev.contrats,
        { date: new Date().toISOString().split('T')[0], employeur: '', type: 'Cachet', nombre: 1, brut: 0 }
      ]
    }));
  };

  const removeContrat = (index: number) => {
    setData(prev => {
      const newContrats = [...prev.contrats];
      newContrats.splice(index, 1);
      return { ...prev, contrats: newContrats };
    });
  };

  const exportData = () => {
    const dataStr = JSON.stringify(data, null, 2);
    const blob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'simulation_intermittence.json';
    a.click();
    URL.revokeObjectURL(url);
  };

  const importData = (jsonData: string) => {
    try {
      const parsedData = JSON.parse(jsonData);
      setData(parsedData);
    } catch (error) {
      console.error('Erreur lors de l\'import des données', error);
      alert('Le fichier importé contient des données invalides.');
    }
  };

  // Sauvegarder la période actuelle lors d'un renouvellement
  const sauvegarderPeriode = () => {
    if (!data.dateFinContrat || !data.dateIndem) {
      alert('Veuillez définir la date de fin de contrat et la date d\'indemnisation avant de sauvegarder.');
      return;
    }

    // Filtrer les contrats dans la période de suivi (12 mois après la date de fin de contrat)
    const dateFinContrat = new Date(data.dateFinContrat);
    const dateAnniversaire = new Date(dateFinContrat);
    dateAnniversaire.setFullYear(dateAnniversaire.getFullYear() + 1);
    
    const contratsDansPeriode = data.contrats.filter(contrat => {
      const dateContrat = new Date(contrat.date);
      return dateContrat > dateFinContrat && dateContrat <= dateAnniversaire;
    });

    // Calculer les totaux de la période
    const totalHeures = contratsDansPeriode.reduce(
      (acc, c) => acc + (c.type === 'Cachet' ? c.nombre * 12 : c.nombre),
      0
    );
    const totalBrut = contratsDansPeriode.reduce((acc, c) => acc + c.brut, 0);

    const nouvellePeriode: PeriodeSauvegardee = {
      id: `periode-${Date.now()}`,
      dateSauvegarde: new Date().toISOString().split('T')[0],
      dateFinContrat: data.dateFinContrat,
      dateIndem: data.dateIndem,
      // Sauvegarder toutes les données AJ
      montantNet: data.montantNet,
      ajNette: data.ajNette,
      ajBrute: data.ajBrute,
      tauxPrelevement: data.tauxPrelevement,
      delaiAttente: data.delaiAttente,
      franchiseConges: data.franchiseConges,
      joursConges: data.joursConges,
      franchiseSalaires: data.franchiseSalaires,
      joursSalaires: data.joursSalaires,
      annexe: data.annexe,
      contrats: contratsDansPeriode,
      totalHeures,
      totalBrut
    };

    setData(prev => ({
      ...prev,
      periodesSauvegardees: [...(prev.periodesSauvegardees || []), nouvellePeriode]
    }));

    alert(`Période sauvegardée avec succès !\nPériode de suivi : ${dateFinContrat.toLocaleDateString('fr-FR')} - ${dateAnniversaire.toLocaleDateString('fr-FR')}\n${contratsDansPeriode.length} contrat(s) sauvegardé(s)`);
  };

  // Restaurer une période sauvegardée
  const restaurerPeriode = (periodeId: string) => {
    const periodes = data.periodesSauvegardees || [];
    const periode = periodes.find(p => p.id === periodeId);
    
    if (!periode) {
      alert('Période non trouvée.');
      return;
    }

    if (!confirm(`Voulez-vous restaurer la période du ${new Date(periode.dateSauvegarde).toLocaleDateString('fr-FR')} ?\n\nCela remplacera vos données actuelles.`)) {
      return;
    }

    setData(prev => ({
      ...prev,
      // Restaurer toutes les données AJ de la période
      dateFinContrat: periode.dateFinContrat,
      dateIndem: periode.dateIndem,
      montantNet: periode.montantNet,
      ajNette: periode.ajNette,
      ajBrute: periode.ajBrute,
      tauxPrelevement: periode.tauxPrelevement,
      delaiAttente: periode.delaiAttente,
      franchiseConges: periode.franchiseConges,
      joursConges: periode.joursConges,
      franchiseSalaires: periode.franchiseSalaires,
      joursSalaires: periode.joursSalaires,
      annexe: periode.annexe,
      contrats: periode.contrats
    }));

    alert('Période restaurée avec succès !');
  };

  // Supprimer une période sauvegardée
  const supprimerPeriode = (periodeId: string) => {
    if (!confirm('Voulez-vous vraiment supprimer cette période sauvegardée ?')) {
      return;
    }

    setData(prev => ({
      ...prev,
      periodesSauvegardees: (prev.periodesSauvegardees || []).filter(p => p.id !== periodeId)
    }));
  };

  // Créer une nouvelle période (après renouvellement)
  const creerNouvellePeriode = () => {
    if (!data.dateFinContrat || !data.dateIndem) {
      alert('Veuillez d\'abord sauvegarder votre période actuelle avant de créer une nouvelle période.');
      return;
    }

    if (!confirm('Voulez-vous créer une nouvelle période de suivi ?\n\nVos données actuelles seront sauvegardées et vous pourrez ensuite définir votre nouvelle AJ et vos nouveaux contrats.')) {
      return;
    }

    // Sauvegarder d'abord la période actuelle
    sauvegarderPeriode();

    // Calculer les nouvelles dates (date anniversaire devient la nouvelle date de fin)
    const dateFinContratActuelle = new Date(data.dateFinContrat);
    const nouvelleDateFinContrat = new Date(dateFinContratActuelle);
    nouvelleDateFinContrat.setFullYear(nouvelleDateFinContrat.getFullYear() + 1);

    const nouvelleDateIndem = new Date(nouvelleDateFinContrat);
    nouvelleDateIndem.setDate(nouvelleDateIndem.getDate() + 2); // 2 jours après

    // Réinitialiser pour la nouvelle période en gardant les anciens contrats
    setData(prev => ({
      ...prev,
      dateFinContrat: nouvelleDateFinContrat.toISOString().split('T')[0],
      dateIndem: nouvelleDateIndem.toISOString().split('T')[0],
      // Garder montantNet, ajNette, ajBrute, etc. vides pour que l'utilisateur les remplisse
      montantNet: '',
      ajNette: '',
      ajBrute: ''
      // Les contrats sont conservés, l'utilisateur peut ajouter les nouveaux
    }));

    alert(`Nouvelle période créée !\n\nNouvelle date de fin de contrat : ${nouvelleDateFinContrat.toLocaleDateString('fr-FR')}\nDate d'indemnisation : ${nouvelleDateIndem.toLocaleDateString('fr-FR')}\n\nVous pouvez maintenant mettre à jour votre AJ et ajouter vos nouveaux contrats.`);
  };

  // Gestion des employeurs
  const addEmployeur = (employeur: Omit<Employeur, 'id'>) => {
    const nouvelEmployeur: Employeur = {
      ...employeur,
      id: `emp-${Date.now()}`
    };
    setData(prev => ({
      ...prev,
      employeurs: [...(prev.employeurs || []), nouvelEmployeur]
    }));
  };

  const updateEmployeur = (id: string, employeurData: Partial<Employeur>) => {
    setData(prev => ({
      ...prev,
      employeurs: (prev.employeurs || []).map(emp =>
        emp.id === id ? { ...emp, ...employeurData } : emp
      )
    }));
  };

  const removeEmployeur = (id: string) => {
    if (!confirm('Voulez-vous vraiment supprimer cet employeur ?')) {
      return;
    }
    setData(prev => ({
      ...prev,
      employeurs: (prev.employeurs || []).filter(emp => emp.id !== id)
    }));
  };

  const getEmployeurById = (id: string): Employeur | undefined => {
    return (data.employeurs || []).find(emp => emp.id === id);
  };

  // Gestion des contrats simulés
  const addContratSimule = (contrat: Omit<Contrat, 'statut'>) => {
    setData(prev => ({
      ...prev,
      contratsSimules: [
        ...(prev.contratsSimules || []),
        { ...contrat, statut: 'complet' }
      ]
    }));
  };

  const updateContratSimule = (index: number, field: keyof Contrat, value: any) => {
    setData(prev => {
      const nouveauxContratsSimules = [...(prev.contratsSimules || [])];
      nouveauxContratsSimules[index] = { ...nouveauxContratsSimules[index], [field]: value };
      return { ...prev, contratsSimules: nouveauxContratsSimules };
    });
  };

  const removeContratSimule = (index: number) => {
    setData(prev => {
      const nouveauxContratsSimules = [...(prev.contratsSimules || [])];
      nouveauxContratsSimules.splice(index, 1);
      return { ...prev, contratsSimules: nouveauxContratsSimules };
    });
  };

  const clearContratsSimules = () => {
    setData(prev => ({
      ...prev,
      contratsSimules: []
    }));
  };

  // Détection d'anomalies
  const detecterAnomalies = () => {
    const incomplets: Contrat[] = [];
    const impayes: Contrat[] = [];
    const doublons: Contrat[][] = [];

    // Détecter les contrats incomplets (sans employeur ou sans montant)
    data.contrats.forEach(contrat => {
      if (!contrat.employeur || contrat.brut === 0) {
        incomplets.push(contrat);
      }
    });

    // Détecter les contrats impayés (marqués comme tels)
    data.contrats.forEach(contrat => {
      if (contrat.statut === 'impaye') {
        impayes.push(contrat);
      }
    });

    // Détecter les doublons (même date, même employeur, même type)
    const groupes = new Map<string, Contrat[]>();
    data.contrats.forEach(contrat => {
      const cle = `${contrat.date}-${contrat.employeur}-${contrat.type}`;
      if (!groupes.has(cle)) {
        groupes.set(cle, []);
      }
      groupes.get(cle)!.push(contrat);
    });

    groupes.forEach(groupe => {
      if (groupe.length > 1) {
        doublons.push(groupe);
      }
    });

    return { incomplets, impayes, doublons };
  };

  const value = {
    data,
    setData,
    updateField,
    updateContrat,
    addContrat,
    removeContrat,
    addEmployeur,
    updateEmployeur,
    removeEmployeur,
    getEmployeurById,
    sauvegarderPeriode,
    restaurerPeriode,
    supprimerPeriode,
    creerNouvellePeriode,
    addContratSimule,
    updateContratSimule,
    removeContratSimule,
    clearContratsSimules,
    detecterAnomalies,
    exportData,
    importData
  };

  return (
    <IntermittenceContext.Provider value={value}>
      {children}
    </IntermittenceContext.Provider>
  );
}; 