import React from 'react';
import { useIntermittence } from '../context/IntermittenceContext';
import { AlertTriangle, AlertCircle, Copy, FileX } from 'lucide-react';
import ImportExportBar from '../components/ImportExportBar';

const AnomaliesPage: React.FC = () => {
  const { data, detecterAnomalies, updateContrat } = useIntermittence();
  const anomalies = detecterAnomalies();

  const getHeuresConverties = (contrat: any) => {
    return contrat.type === 'Cachet' ? contrat.nombre * 12 : contrat.nombre;
  };

  const findContratIndex = (contrat: any) => {
    return data.contrats.findIndex(c =>
      c.date === contrat.date &&
      c.employeur === contrat.employeur &&
      c.type === contrat.type &&
      c.nombre === contrat.nombre
    );
  };

  const marquerCommeComplete = (contrat: any) => {
    const index = findContratIndex(contrat);
    if (index !== -1) {
      updateContrat(index, 'statut', 'complet');
    }
  };

  // Fonction commentée pour une future utilisation
  // const marquerCommeImpaye = (contrat: any) => {
  //   const index = findContratIndex(contrat);
  //   if (index !== -1) {
  //     updateContrat(index, 'statut', 'impaye');
  //   }
  // };

  const totalAnomalies = anomalies.incomplets.length + anomalies.impayes.length + anomalies.doublons.length;

  return (
    <div className="p-6">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-800 mb-2">Détection d'anomalies</h1>
        <p className="text-gray-600">
          Identification automatique des contrats incomplets, impayés ou en doublon.
        </p>
      </div>

      <ImportExportBar />

      {/* Résumé */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
        <div className="bg-white rounded-lg shadow p-4 border-l-4 border-red-500">
          <div className="flex items-center">
            <FileX className="w-8 h-8 text-red-500 mr-3" />
            <div>
              <p className="text-2xl font-bold text-gray-800">{anomalies.incomplets.length}</p>
              <p className="text-sm text-gray-600">Contrats incomplets</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow p-4 border-l-4 border-amber-500">
          <div className="flex items-center">
            <AlertTriangle className="w-8 h-8 text-amber-500 mr-3" />
            <div>
              <p className="text-2xl font-bold text-gray-800">{anomalies.impayes.length}</p>
              <p className="text-sm text-gray-600">Contrats impayés</p>
            </div>
          </div>
        </div>

        <div className="bg-white rounded-lg shadow p-4 border-l-4 border-blue-500">
          <div className="flex items-center">
            <Copy className="w-8 h-8 text-blue-500 mr-3" />
            <div>
              <p className="text-2xl font-bold text-gray-800">{anomalies.doublons.length}</p>
              <p className="text-sm text-gray-600">Groupes de doublons</p>
            </div>
          </div>
        </div>
      </div>

      {totalAnomalies === 0 ? (
        <div className="bg-green-50 rounded-lg p-8 text-center">
          <AlertCircle className="w-12 h-12 text-green-600 mx-auto mb-3" />
          <h3 className="text-lg font-semibold text-green-800 mb-2">Aucune anomalie détectée</h3>
          <p className="text-green-700">Tous vos contrats sont complets et cohérents.</p>
        </div>
      ) : (
        <div className="space-y-6">
          {/* Contrats incomplets */}
          {anomalies.incomplets.length > 0 && (
            <div className="bg-white rounded-lg shadow overflow-hidden">
              <div className="bg-red-500 text-white px-4 py-3 flex items-center">
                <FileX className="w-5 h-5 mr-2" />
                <h3 className="font-semibold">Contrats incomplets ({anomalies.incomplets.length})</h3>
              </div>
              <div className="divide-y">
                {anomalies.incomplets.map((contrat, index) => (
                  <div key={index} className="p-4 hover:bg-gray-50">
                    <div className="flex items-start justify-between">
                      <div className="flex-grow">
                        <p className="font-semibold text-gray-800">
                          {new Date(contrat.date).toLocaleDateString('fr-FR')}
                          {contrat.employeur && ` - ${contrat.employeur}`}
                        </p>
                        <p className="text-sm text-gray-600 mt-1">
                          {contrat.type}: {contrat.nombre} ({getHeuresConverties(contrat)}h)
                          {contrat.brut > 0 && ` - ${contrat.brut.toFixed(2)}€`}
                        </p>
                        <div className="mt-2">
                          {!contrat.employeur && (
                            <span className="inline-block bg-red-100 text-red-700 text-xs px-2 py-1 rounded mr-2">
                              Employeur manquant
                            </span>
                          )}
                          {contrat.brut === 0 && (
                            <span className="inline-block bg-red-100 text-red-700 text-xs px-2 py-1 rounded">
                              Montant manquant
                            </span>
                          )}
                        </div>
                      </div>
                      <button
                        onClick={() => marquerCommeComplete(contrat)}
                        className="ml-4 px-3 py-1 bg-green-600 text-white text-sm rounded hover:bg-green-700"
                      >
                        Marquer comme complet
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Contrats impayés */}
          {anomalies.impayes.length > 0 && (
            <div className="bg-white rounded-lg shadow overflow-hidden">
              <div className="bg-amber-500 text-white px-4 py-3 flex items-center">
                <AlertTriangle className="w-5 h-5 mr-2" />
                <h3 className="font-semibold">Contrats impayés ({anomalies.impayes.length})</h3>
              </div>
              <div className="divide-y">
                {anomalies.impayes.map((contrat, index) => (
                  <div key={index} className="p-4 hover:bg-gray-50">
                    <div className="flex items-start justify-between">
                      <div className="flex-grow">
                        <p className="font-semibold text-gray-800">
                          {new Date(contrat.date).toLocaleDateString('fr-FR')} - {contrat.employeur}
                        </p>
                        <p className="text-sm text-gray-600 mt-1">
                          {contrat.type}: {contrat.nombre} ({getHeuresConverties(contrat)}h) - {contrat.brut.toFixed(2)}€
                        </p>
                        {contrat.notes && (
                          <p className="text-sm text-amber-600 mt-1 italic">
                            Note: {contrat.notes}
                          </p>
                        )}
                      </div>
                      <button
                        onClick={() => marquerCommeComplete(contrat)}
                        className="ml-4 px-3 py-1 bg-green-600 text-white text-sm rounded hover:bg-green-700"
                      >
                        Marquer comme payé
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Doublons */}
          {anomalies.doublons.length > 0 && (
            <div className="bg-white rounded-lg shadow overflow-hidden">
              <div className="bg-blue-500 text-white px-4 py-3 flex items-center">
                <Copy className="w-5 h-5 mr-2" />
                <h3 className="font-semibold">Doublons potentiels ({anomalies.doublons.length} groupes)</h3>
              </div>
              <div className="divide-y">
                {anomalies.doublons.map((groupe, groupeIndex) => (
                  <div key={groupeIndex} className="p-4 bg-blue-50">
                    <p className="text-sm font-medium text-blue-800 mb-2">
                      Groupe {groupeIndex + 1} - {groupe.length} contrats similaires
                    </p>
                    <div className="space-y-2">
                      {groupe.map((contrat, index) => (
                        <div key={index} className="bg-white p-3 rounded border border-blue-200">
                          <p className="text-sm text-gray-800">
                            <strong>{new Date(contrat.date).toLocaleDateString('fr-FR')}</strong> - {contrat.employeur}
                          </p>
                          <p className="text-sm text-gray-600">
                            {contrat.type}: {contrat.nombre} ({getHeuresConverties(contrat)}h) - {contrat.brut.toFixed(2)}€
                          </p>
                        </div>
                      ))}
                    </div>
                    <p className="text-xs text-blue-600 mt-2">
                      ⚠️ Vérifiez que ces contrats ne sont pas des doublons
                    </p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      )}

      {/* Aide */}
      <div className="mt-6 bg-gray-50 rounded-lg p-4 text-sm text-gray-700">
        <h4 className="font-semibold mb-2">💡 À propos de la détection d'anomalies</h4>
        <ul className="list-disc list-inside space-y-1">
          <li><strong>Contrats incomplets :</strong> Contrats sans employeur ou sans montant brut</li>
          <li><strong>Contrats impayés :</strong> Contrats marqués manuellement comme impayés</li>
          <li><strong>Doublons :</strong> Contrats avec la même date, le même employeur et le même type</li>
        </ul>
      </div>
    </div>
  );
};

export default AnomaliesPage;
