import React, { useState } from 'react';
import { useIntermittence, getContratsDansFenetre12Mois } from '../context/IntermittenceContext';
import { Plus, Trash, TrendingUp, Calendar, AlertCircle, RefreshCw } from 'lucide-react';
import ImportExportBar from '../components/ImportExportBar';

const SimulationPage: React.FC = () => {
  const {
    data,
    addContratSimule,
    removeContratSimule,
    clearContratsSimules,
    getEmployeurById
  } = useIntermittence();

  const [nouveauContrat, setNouveauContrat] = useState({
    date: new Date().toISOString().split('T')[0],
    employeur: '',
    employeurId: '',
    type: 'Cachet' as 'Cachet' | 'Heures',
    nombre: 1,
    brut: 0
  });

  // Calculer les heures actuelles (contrats réels)
  const contratsReels = getContratsDansFenetre12Mois(data.contrats, data.dateFinContrat);
  const heuresReelles = contratsReels.reduce(
    (acc, c) => acc + (c.type === 'Cachet' ? c.nombre * 12 : c.nombre),
    0
  );

  // Calculer les heures avec simulation
  const contratsSimules = data.contratsSimules || [];
  const heuresSimulees = contratsSimules.reduce(
    (acc, c) => acc + (c.type === 'Cachet' ? c.nombre * 12 : c.nombre),
    0
  );

  const heuresTotales = heuresReelles + heuresSimulees;
  const heuresManquantes = Math.max(0, 507 - heuresTotales);
  const heuresExcedentaires = Math.max(0, heuresTotales - 507);
  const eligibilite = heuresTotales >= 507;

  // Calcul de la nouvelle date de fin de droits estimée
  const calculerNouvelleDateFinDroits = () => {
    if (!data.dateFinContrat || contratsSimules.length === 0) return null;

    // Trouver la date du dernier contrat simulé
    const datesSimulees = contratsSimules.map(c => new Date(c.date));
    const derniereDateSimulee = new Date(Math.max(...datesSimulees.map(d => d.getTime())));

    // Ajouter la durée d'indemnisation estimée (environ 1 an)
    const nouvelleDate = new Date(derniereDateSimulee);
    nouvelleDate.setFullYear(nouvelleDate.getFullYear() + 1);

    return nouvelleDate;
  };

  const nouvelleDateFinDroits = calculerNouvelleDateFinDroits();

  const handleAjouterContrat = () => {
    if (!nouveauContrat.employeur.trim()) {
      alert('Le nom de l\'employeur est obligatoire');
      return;
    }

    addContratSimule(nouveauContrat);
    setNouveauContrat({
      date: new Date().toISOString().split('T')[0],
      employeur: '',
      employeurId: '',
      type: 'Cachet',
      nombre: 1,
      brut: 0
    });
  };

  const handleEmployeurChange = (employeurId: string) => {
    if (employeurId) {
      const employeur = getEmployeurById(employeurId);
      if (employeur) {
        setNouveauContrat({
          ...nouveauContrat,
          employeurId,
          employeur: employeur.nom
        });
      }
    } else {
      setNouveauContrat({
        ...nouveauContrat,
        employeurId: '',
        employeur: ''
      });
    }
  };

  const getHeuresConverties = (contrat: any) => {
    return contrat.type === 'Cachet' ? contrat.nombre * 12 : contrat.nombre;
  };

  const employeurs = data.employeurs || [];

  return (
    <div className="p-6">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-800 mb-2 flex items-center gap-2">
          <TrendingUp className="w-7 h-7 text-blue-600" />
          Simulation - Examen anticipé
        </h1>
        <p className="text-gray-600">
          Simulez l'ajout de contrats futurs pour anticiper votre situation.
        </p>
      </div>

      <ImportExportBar />

      {/* Indicateurs de simulation */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
        <div className="bg-white rounded-lg shadow p-4">
          <p className="text-sm text-gray-600 mb-1">Heures réelles</p>
          <p className="text-2xl font-bold text-blue-600">{heuresReelles}h</p>
        </div>

        <div className="bg-white rounded-lg shadow p-4">
          <p className="text-sm text-gray-600 mb-1">Heures simulées</p>
          <p className="text-2xl font-bold text-purple-600">{heuresSimulees}h</p>
        </div>

        <div className="bg-white rounded-lg shadow p-4">
          <p className="text-sm text-gray-600 mb-1">Total projeté</p>
          <p className="text-2xl font-bold text-gray-800">{heuresTotales}h</p>
          <p className="text-xs text-gray-500 mt-1">Objectif: 507h</p>
        </div>

        <div className={`bg-white rounded-lg shadow p-4 border-l-4 ${eligibilite ? 'border-green-500' : 'border-red-500'}`}>
          <p className="text-sm text-gray-600 mb-1">Statut</p>
          <p className={`text-lg font-bold ${eligibilite ? 'text-green-600' : 'text-red-600'}`}>
            {eligibilite ? '✓ Éligible' : '✗ Non éligible'}
          </p>
          {!eligibilite && heuresManquantes > 0 && (
            <p className="text-xs text-red-600 mt-1">
              Manque {heuresManquantes}h ({Math.ceil(heuresManquantes / 12)} cachets)
            </p>
          )}
          {eligibilite && heuresExcedentaires > 0 && (
            <p className="text-xs text-green-600 mt-1">
              +{heuresExcedentaires}h excédentaires
            </p>
          )}
        </div>
      </div>

      {/* Prédiction de la nouvelle date de fin de droits */}
      {nouvelleDateFinDroits && eligibilite && (
        <div className="bg-gradient-to-r from-blue-50 to-purple-50 rounded-lg p-4 mb-6 border border-blue-200">
          <div className="flex items-start gap-3">
            <Calendar className="w-6 h-6 text-blue-600 mt-1" />
            <div>
              <h3 className="font-semibold text-gray-800 mb-1">Nouvelle date de fin de droits estimée</h3>
              <p className="text-lg font-bold text-blue-600">
                {nouvelleDateFinDroits.toLocaleDateString('fr-FR', {
                  day: 'numeric',
                  month: 'long',
                  year: 'numeric'
                })}
              </p>
              <p className="text-sm text-gray-600 mt-1">
                Basé sur le dernier contrat simulé + 1 an d'indemnisation estimée
              </p>
            </div>
          </div>
        </div>
      )}

      {/* Formulaire d'ajout de contrat simulé */}
      <div className="bg-white rounded-lg shadow p-6 mb-6">
        <h3 className="text-lg font-semibold mb-4 flex items-center gap-2">
          <Plus className="w-5 h-5" />
          Ajouter un contrat futur
        </h3>

        <div className="grid grid-cols-1 md:grid-cols-6 gap-4">
          <div className="md:col-span-1">
            <label className="block text-sm font-medium text-gray-700 mb-1">Date</label>
            <input
              type="date"
              value={nouveauContrat.date}
              onChange={(e) => setNouveauContrat({ ...nouveauContrat, date: e.target.value })}
              className="w-full p-2 border rounded-md"
            />
          </div>

          <div className="md:col-span-2">
            <label className="block text-sm font-medium text-gray-700 mb-1">Employeur</label>
            <div className="flex gap-2">
              {employeurs.length > 0 && (
                <select
                  value={nouveauContrat.employeurId}
                  onChange={(e) => handleEmployeurChange(e.target.value)}
                  className="flex-grow p-2 border rounded-md"
                >
                  <option value="">Choisir ou saisir...</option>
                  {employeurs.map(emp => (
                    <option key={emp.id} value={emp.id}>{emp.nom}</option>
                  ))}
                </select>
              )}
              <input
                type="text"
                value={nouveauContrat.employeur}
                onChange={(e) => setNouveauContrat({ ...nouveauContrat, employeur: e.target.value, employeurId: '' })}
                className="flex-grow p-2 border rounded-md"
                placeholder="Nom de l'employeur"
              />
            </div>
          </div>

          <div className="md:col-span-1">
            <label className="block text-sm font-medium text-gray-700 mb-1">Type</label>
            <select
              value={nouveauContrat.type}
              onChange={(e) => setNouveauContrat({ ...nouveauContrat, type: e.target.value as 'Cachet' | 'Heures' })}
              className="w-full p-2 border rounded-md"
            >
              <option value="Cachet">Cachet</option>
              <option value="Heures">Heures</option>
            </select>
          </div>

          <div className="md:col-span-1">
            <label className="block text-sm font-medium text-gray-700 mb-1">Nombre</label>
            <input
              type="number"
              value={nouveauContrat.nombre}
              onChange={(e) => setNouveauContrat({ ...nouveauContrat, nombre: parseInt(e.target.value) || 0 })}
              className="w-full p-2 border rounded-md"
              min="0"
            />
          </div>

          <div className="md:col-span-1">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Brut (€)
            </label>
            <input
              type="number"
              value={nouveauContrat.brut}
              onChange={(e) => setNouveauContrat({ ...nouveauContrat, brut: parseFloat(e.target.value) || 0 })}
              className="w-full p-2 border rounded-md"
              min="0"
              step="0.01"
            />
          </div>
        </div>

        <div className="mt-4 flex gap-2">
          <button
            onClick={handleAjouterContrat}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700"
          >
            <Plus className="w-4 h-4" />
            Ajouter à la simulation
          </button>
          {contratsSimules.length > 0 && (
            <button
              onClick={clearContratsSimules}
              className="flex items-center gap-2 px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700"
            >
              <RefreshCw className="w-4 h-4" />
              Réinitialiser la simulation
            </button>
          )}
        </div>
      </div>

      {/* Liste des contrats simulés */}
      {contratsSimules.length > 0 && (
        <div className="bg-white rounded-lg shadow mb-6 overflow-hidden">
          <div className="bg-purple-600 text-white px-4 py-3">
            <h3 className="font-semibold">
              Contrats simulés ({contratsSimules.length})
            </h3>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full">
              <thead className="bg-gray-100 border-b">
                <tr>
                  <th className="px-4 py-2 text-left text-sm font-semibold">Date</th>
                  <th className="px-4 py-2 text-left text-sm font-semibold">Employeur</th>
                  <th className="px-4 py-2 text-left text-sm font-semibold">Type</th>
                  <th className="px-4 py-2 text-right text-sm font-semibold">Nombre</th>
                  <th className="px-4 py-2 text-right text-sm font-semibold">Heures</th>
                  <th className="px-4 py-2 text-right text-sm font-semibold">Brut</th>
                  <th className="px-4 py-2 text-center text-sm font-semibold">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y">
                {contratsSimules.map((contrat, index) => (
                  <tr key={index} className="hover:bg-purple-50">
                    <td className="px-4 py-3 text-sm">
                      {new Date(contrat.date).toLocaleDateString('fr-FR')}
                    </td>
                    <td className="px-4 py-3 text-sm">{contrat.employeur}</td>
                    <td className="px-4 py-3 text-sm">{contrat.type}</td>
                    <td className="px-4 py-3 text-sm text-right">{contrat.nombre}</td>
                    <td className="px-4 py-3 text-sm text-right font-medium">
                      {getHeuresConverties(contrat)}h
                    </td>
                    <td className="px-4 py-3 text-sm text-right">{contrat.brut.toFixed(2)}€</td>
                    <td className="px-4 py-3 text-center">
                      <button
                        onClick={() => removeContratSimule(index)}
                        className="text-red-600 hover:text-red-800"
                        title="Supprimer"
                      >
                        <Trash className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Aide */}
      <div className="bg-amber-50 rounded-lg p-4 text-sm text-amber-900">
        <div className="flex items-start gap-2">
          <AlertCircle className="w-5 h-5 flex-shrink-0 mt-0.5" />
          <div>
            <h4 className="font-semibold mb-1">💡 À propos de la simulation</h4>
            <p>
              Cette page vous permet de simuler l'ajout de contrats futurs pour anticiper votre situation.
              Les contrats simulés ne sont pas sauvegardés et n'affectent pas vos données réelles.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SimulationPage;
